```c
/**
 * Returns the number of KV cache rows needed for a sequence of `len` tokens
 * given a cache capacity of `cap`. If `len` exceeds `cap`, returns `cap`;
 * otherwise returns `len`. Handles edge cases where `len` or `cap` is non-positive.
 */
int kv_rows_needed(int len, int cap) {
    if (len <= 0) return 0;
    if (cap <= 0) return len;
    return len < cap ? len : cap;
}
```
